-- PostgreSQL/Supabase production schema counterpart. Apply only after Auth adapter work.
create table if not exists public.users (id uuid primary key default gen_random_uuid(), auth_user_id uuid unique, name text not null, long_term_goal text not null, current_stage text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table if not exists public.self_entries (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.users(id) on delete cascade, client_request_id uuid not null unique, content text not null check (char_length(content) between 10 and 10000), category text not null, tags text[] not null default '{}', importance smallint not null check (importance between 1 and 5), occurred_at timestamptz not null, allow_ai boolean not null default true, source_type text not null default 'user_input', status text not null default 'active', metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create index if not exists self_entries_user_time_idx on public.self_entries(user_id, occurred_at desc) where deleted_at is null;
create table if not exists public.profile_update_proposals (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.users(id) on delete cascade, source_entry_id uuid not null references public.self_entries(id), proposed_content text not null, fact_type text not null, evidence_excerpt text not null, confidence numeric not null check (confidence between 0 and 1), possible_impact text not null, status text not null default 'pending' check (status in ('pending','approved','rejected')), model_mode text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), decided_at timestamptz, deleted_at timestamptz);
create index if not exists proposals_user_status_idx on public.profile_update_proposals(user_id,status,created_at desc) where deleted_at is null;
create table if not exists public.profile_facts (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.users(id) on delete cascade, proposal_id uuid not null unique references public.profile_update_proposals(id), content text not null, fact_type text not null, confidence numeric not null check (confidence between 0 and 1), user_confirmed boolean not null default true, is_active boolean not null default true, source_type text not null, source_id uuid not null, version integer not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table if not exists public.profile_fact_versions (id uuid primary key default gen_random_uuid(), profile_fact_id uuid not null references public.profile_facts(id) on delete cascade, version integer not null, content text not null, confidence numeric not null, change_reason text not null, changed_by text not null, created_at timestamptz not null default now(), unique(profile_fact_id,version));
create table if not exists public.life_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.users(id) on delete cascade, event_type text not null, title text not null, summary text not null, source_type text not null, source_id uuid not null, occurred_at timestamptz not null, created_at timestamptz not null default now(), metadata jsonb not null default '{}', deleted_at timestamptz);
create index if not exists life_events_user_time_idx on public.life_events(user_id,occurred_at desc) where deleted_at is null;
